/// <summary>
/// Extension of METItemSiteSettingsSetup
/// </summary>
[ExtensionOf(tableStr(METItemSiteSettingsSetup))]
Public final class METItemSiteSettingsSetupTable_Extension
{
}

Method.Source:
    //TODO: move this code to MetItemSiteSettingsSetup.Update when MET Price Model code is merged into MET model 
    /// <summary>
    /// CoC on update
    /// </summary>
    public void update()
    {
        boolean     fieldUpdated = false;
        MetItemSiteSettingsSetup metItemSiteSettingsSetupOrig = this.orig();

        if(this.SubrangeId      != metItemSiteSettingsSetupOrig.SubrangeId
        || this.ItemType        != metItemSiteSettingsSetupOrig.ItemType
        || this.MTCLegacyCode   != metItemSiteSettingsSetupOrig.MTCLegacyCode
        || this.DeletionReason  != metItemSiteSettingsSetupOrig.DeletionReason
        || this.PublishPriceBook != metItemSiteSettingsSetupOrig.PublishPriceBook
        || this.PublishPortal   != metItemSiteSettingsSetupOrig.PublishPortal
        || this.PublishHost     != metItemSiteSettingsSetupOrig.PublishHost
        || this.ItemStatus      == METConstants::Active)
        {
            fieldUpdated = true;
        }
        
        next update();

        if(fieldUpdated)
        {
            METPriceChangeEventProduct::metProcessTrackChange(this.InventTable(), METConstants::emptyString, this.InventSiteId);
        }
    }
